-- V Coin complete schema for Supabase PostgreSQL
create extension if not exists pgcrypto;

do $$ begin create type public.app_role as enum ('super_admin','admin','master','user'); exception when duplicate_object then null; end $$;
do $$ begin create type public.user_status as enum ('active','inactive','suspended'); exception when duplicate_object then null; end $$;
do $$ begin create type public.wallet_status as enum ('active','frozen'); exception when duplicate_object then null; end $$;
do $$ begin create type public.tx_direction as enum ('CREDIT','DEBIT'); exception when duplicate_object then null; end $$;
do $$ begin create type public.request_status as enum ('pending','approved','payment_pending','payment_submitted','payment_confirmed','completed','rejected','cancelled'); exception when duplicate_object then null; end $$;

create table if not exists public.profiles(
 id uuid primary key references auth.users(id) on delete cascade, username text unique not null, full_name text, email text unique, phone text, role public.app_role not null default 'user', master_id uuid references public.profiles(id), status public.user_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.permissions(code text primary key, label text not null);
create table if not exists public.user_permissions(user_id uuid references public.profiles(id) on delete cascade, permission_code text references public.permissions(code) on delete cascade, granted boolean not null default true, primary key(user_id,permission_code));
create table if not exists public.wallets(id uuid primary key default gen_random_uuid(), user_id uuid unique not null references public.profiles(id) on delete cascade, wallet_address text unique not null, vcoin_balance numeric(24,8) not null default 0 check(vcoin_balance>=0), locked_balance numeric(24,8) not null default 0 check(locked_balance>=0 and locked_balance<=vcoin_balance), status public.wallet_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.wallet_transactions(id uuid primary key default gen_random_uuid(), transaction_id text unique not null, wallet_id uuid not null references public.wallets(id), transaction_type text not null, direction public.tx_direction not null, amount numeric(24,8) not null check(amount>0), balance_before numeric(24,8) not null, balance_after numeric(24,8) not null, reference_id text, description text, idempotency_key text unique, created_at timestamptz not null default now());
create table if not exists public.vcoin_transfers(id uuid primary key default gen_random_uuid(), transaction_id text unique not null, sender_user_id uuid not null references public.profiles(id), receiver_user_id uuid not null references public.profiles(id), sender_wallet_id uuid not null references public.wallets(id), receiver_wallet_id uuid not null references public.wallets(id), amount numeric(24,8) not null check(amount>0), charge numeric(24,8) not null default 0, total_debit numeric(24,8) not null, transfer_method text not null check(transfer_method in ('USERNAME','WALLET_ADDRESS','QR_CODE')), status text not null default 'completed', idempotency_key text unique not null, created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists public.topup_requests(id uuid primary key default gen_random_uuid(), request_id text unique not null, user_id uuid not null references public.profiles(id), master_id uuid references public.profiles(id), requested_vcoin numeric(24,8) not null check(requested_vcoin>0), payment_amount numeric(24,8), payment_currency text default 'INR', topup_charge numeric(24,8) not null default 0, total_payment numeric(24,8), status public.request_status not null default 'pending', idempotency_key text unique not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.topup_payments(id uuid primary key default gen_random_uuid(), topup_request_id uuid not null references public.topup_requests(id), payment_method text, payment_reference text, amount numeric(24,8), payment_proof text, status text, verified_by uuid references public.profiles(id), verified_at timestamptz, created_at timestamptz default now());
create table if not exists public.charge_rules(id uuid primary key default gen_random_uuid(), master_id uuid references public.profiles(id), charge_type text not null, charge_mode text not null check(charge_mode in('FIXED','PERCENTAGE')), charge_value numeric(24,8) not null default 0, minimum_charge numeric(24,8), maximum_charge numeric(24,8), is_active boolean not null default true, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.charge_history(id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id), master_id uuid references public.profiles(id), transaction_type text not null, reference_id text, amount numeric(24,8) not null, created_at timestamptz not null default now());
create table if not exists public.commission_rules(id uuid primary key default gen_random_uuid(), master_id uuid unique not null references public.profiles(id) on delete cascade, master_percentage numeric(9,6) not null default 0 check(master_percentage between 0 and 100), company_percentage numeric(9,6) not null default 100 check(company_percentage between 0 and 100), is_active boolean not null default true, created_at timestamptz default now());
create table if not exists public.commissions(id uuid primary key default gen_random_uuid(), master_id uuid references public.profiles(id), user_id uuid references public.profiles(id), transaction_type text not null, transaction_reference text not null, transaction_amount numeric(24,8) not null, total_charge numeric(24,8) not null, master_commission numeric(24,8) not null default 0, company_commission numeric(24,8) not null default 0, status text not null default 'recorded', created_at timestamptz default now());
create table if not exists public.wallet_maintenance_rules(id uuid primary key default gen_random_uuid(), master_id uuid references public.profiles(id), charge_amount numeric(24,8) not null default 0, frequency_hours integer not null default 24 check(frequency_hours>0), minimum_wallet_balance numeric(24,8) not null default 0, is_active boolean not null default false, last_run_at timestamptz, created_at timestamptz default now());
create table if not exists public.crypto_assets(id uuid primary key default gen_random_uuid(), symbol text unique not null, name text not null, network text not null, vcoin_per_unit numeric(24,8) not null default 1 check(vcoin_per_unit>0), network_fee_vcoin numeric(24,8) not null default 0, is_active boolean not null default true);
create table if not exists public.crypto_conversion_requests(id uuid primary key default gen_random_uuid(), request_id text unique not null, user_id uuid not null references public.profiles(id), master_id uuid references public.profiles(id), crypto_asset_id uuid references public.crypto_assets(id), vcoin_amount numeric(24,8) not null, conversion_rate numeric(24,8) not null, gross_crypto_amount numeric(24,8) not null, conversion_charge numeric(24,8) not null default 0, network_charge numeric(24,8) not null default 0, final_crypto_amount numeric(24,8) not null, destination_wallet text not null, status public.request_status not null default 'pending', idempotency_key text unique not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.crypto_transactions(id uuid primary key default gen_random_uuid(), crypto_request_id uuid not null references public.crypto_conversion_requests(id), crypto_asset_id uuid references public.crypto_assets(id), wallet_address text, crypto_amount numeric(24,8), transaction_hash text, network text, processed_by uuid references public.profiles(id), processed_at timestamptz);
create table if not exists public.bank_accounts(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, account_holder_name text not null, bank_name text not null, account_number_encrypted text not null, ifsc_code text not null, account_type text, verification_status text not null default 'pending', created_at timestamptz default now());
create table if not exists public.bank_transfer_requests(id uuid primary key default gen_random_uuid(), request_id text unique not null, user_id uuid not null references public.profiles(id), master_id uuid references public.profiles(id), bank_account_id uuid not null references public.bank_accounts(id), vcoin_amount numeric(24,8) not null, conversion_rate numeric(24,8) not null, gross_bank_amount numeric(24,8) not null, transfer_charge numeric(24,8) not null default 0, final_bank_amount numeric(24,8) not null, status public.request_status not null default 'pending', idempotency_key text unique not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.bank_transfer_transactions(id uuid primary key default gen_random_uuid(), bank_request_id uuid not null references public.bank_transfer_requests(id), bank_reference_number text, amount numeric(24,8), processed_by uuid references public.profiles(id), processed_at timestamptz, remarks text);
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, message text not null, type text, is_read boolean not null default false, reference_id text, created_at timestamptz default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id), action text not null, module text not null, reference_id text, old_data jsonb, new_data jsonb, ip_address inet, created_at timestamptz default now());
create table if not exists public.user_status_history(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), old_status public.user_status, new_status public.user_status not null, changed_by uuid references public.profiles(id), reason text, created_at timestamptz default now());
create table if not exists public.system_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());

create or replace function public.make_wallet_address() returns text language sql volatile as $$ select 'VC-'||upper(substr(encode(gen_random_bytes(12),'hex'),1,24)) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,username,full_name,email) values(new.id,coalesce(nullif(lower(new.raw_user_meta_data->>'username'),''),'user_'||substr(new.id::text,1,8)),new.raw_user_meta_data->>'full_name',new.email);insert into wallets(user_id,wallet_address) values(new.id,make_wallet_address());return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create or replace function public.app_current_role() returns text language sql stable security definer set search_path=public as $$select role::text from profiles where id=auth.uid()$$;
create or replace function public.has_permission(p_permission text) returns boolean language sql stable security definer set search_path=public as $$select coalesce((select role in ('super_admin','admin') from profiles where id=auth.uid()),false) or coalesce((select granted from user_permissions where user_id=auth.uid() and permission_code=p_permission),false)$$;

create or replace function public.calc_charge(p_master uuid,p_type text,p_amount numeric) returns numeric language plpgsql stable security definer set search_path=public as $$declare r record;c numeric:=0;begin select * into r from charge_rules where charge_type=p_type and is_active=true and (master_id=p_master or master_id is null) order by (master_id is not null) desc limit 1;if not found then return 0;end if;if r.charge_mode='FIXED' then c:=r.charge_value;else c:=p_amount*r.charge_value/100;end if;if r.minimum_charge is not null then c:=greatest(c,r.minimum_charge);end if;if r.maximum_charge is not null then c:=least(c,r.maximum_charge);end if;return round(c,8);end$$;

create or replace function public.transfer_vcoin(p_recipient text,p_amount numeric,p_method text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare sprof profiles%rowtype;rprof profiles%rowtype;sw wallets%rowtype;rw wallets%rowtype;charge numeric;total numeric;txid text;mbal numeric;master_comm numeric:=0;company_comm numeric:=0;begin if auth.uid() is null then raise exception 'Not authenticated';end if;if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than zero';end if;if p_idempotency_key is null or length(trim(p_idempotency_key))<8 then raise exception 'Idempotency key required';end if;if exists(select 1 from vcoin_transfers where idempotency_key=p_idempotency_key) then return (select jsonb_build_object('transaction_id',transaction_id,'duplicate',true) from vcoin_transfers where idempotency_key=p_idempotency_key);end if;select * into sprof from profiles where id=auth.uid();if sprof.status<>'active' then raise exception 'Sender is not active';end if;if p_method='USERNAME' then select * into rprof from profiles where lower(username)=lower(trim(leading '@' from p_recipient));else select p.* into rprof from profiles p join wallets w on w.user_id=p.id where w.wallet_address=p_recipient;end if;if rprof.id is null then raise exception 'Recipient not found';end if;if rprof.id=sprof.id then raise exception 'Cannot transfer to yourself';end if;if rprof.status<>'active' then raise exception 'Recipient is not active';end if;select * into sw from wallets where user_id=sprof.id for update;select * into rw from wallets where user_id=rprof.id for update;if sw.status<>'active' or rw.status<>'active' then raise exception 'Wallet is frozen';end if;charge:=calc_charge(sprof.master_id,'INTERNAL_TRANSFER',p_amount);total:=p_amount+charge;if sw.vcoin_balance-sw.locked_balance<total then raise exception 'Insufficient available balance';end if;txid:='VCT-'||upper(substr(encode(gen_random_bytes(10),'hex'),1,20));update wallets set vcoin_balance=vcoin_balance-total,updated_at=now() where id=sw.id;update wallets set vcoin_balance=vcoin_balance+p_amount,updated_at=now() where id=rw.id;insert into vcoin_transfers(transaction_id,sender_user_id,receiver_user_id,sender_wallet_id,receiver_wallet_id,amount,charge,total_debit,transfer_method,status,idempotency_key,completed_at) values(txid,sprof.id,rprof.id,sw.id,rw.id,p_amount,charge,total,p_method,'completed',p_idempotency_key,now());insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(txid||'-D',sw.id,'TRANSFER_SEND','DEBIT',total,sw.vcoin_balance,sw.vcoin_balance-total,txid,'Transfer to @'||rprof.username,p_idempotency_key||'-D'),(txid||'-C',rw.id,'TRANSFER_RECEIVE','CREDIT',p_amount,rw.vcoin_balance,rw.vcoin_balance+p_amount,txid,'Transfer from @'||sprof.username,p_idempotency_key||'-C');if charge>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(sprof.id,sprof.master_id,'INTERNAL_TRANSFER',txid,charge);if sprof.master_id is not null then select round(charge*master_percentage/100,8),round(charge*company_percentage/100,8) into master_comm,company_comm from commission_rules where master_id=sprof.master_id and is_active=true;end if;company_comm:=coalesce(company_comm,charge-master_comm);insert into commissions(master_id,user_id,transaction_type,transaction_reference,transaction_amount,total_charge,master_commission,company_commission) values(sprof.master_id,sprof.id,'INTERNAL_TRANSFER',txid,p_amount,charge,coalesce(master_comm,0),coalesce(company_comm,charge));end if;insert into notifications(user_id,title,message,type,reference_id) values(rprof.id,'V Coin received',p_amount||' VC received from @'||sprof.username,'TRANSFER',txid);return jsonb_build_object('transaction_id',txid,'amount',p_amount,'charge',charge,'total_debit',total,'recipient',rprof.username);end$$;

create or replace function public.admin_adjust_vcoin(p_username text,p_amount numeric,p_direction text,p_note text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare me profiles%rowtype;t profiles%rowtype;w wallets%rowtype;txid text;before numeric;afterb numeric;begin if auth.uid() is null then raise exception 'Not authenticated';end if;select * into me from profiles where id=auth.uid();if me.role not in ('super_admin','admin') or me.status<>'active' then raise exception 'Admin access required';end if;if p_amount<=0 then raise exception 'Amount must be greater than zero';end if;if exists(select 1 from wallet_transactions where idempotency_key=p_idempotency_key) then return jsonb_build_object('duplicate',true);end if;select * into t from profiles where lower(username)=lower(trim(leading '@' from p_username));if t.id is null then raise exception 'User not found';end if;select * into w from wallets where user_id=t.id for update;before:=w.vcoin_balance;if upper(p_direction)='CREDIT' then afterb:=before+p_amount;else if before-w.locked_balance<p_amount then raise exception 'Insufficient available balance';end if;afterb:=before-p_amount;end if;update wallets set vcoin_balance=afterb,updated_at=now() where id=w.id;txid:='ADM-'||upper(substr(encode(gen_random_bytes(10),'hex'),1,20));insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(txid,w.id,case when upper(p_direction)='CREDIT' then 'ADMIN_CREDIT' else 'ADMIN_DEBIT' end,case when upper(p_direction)='CREDIT' then 'CREDIT'::tx_direction else 'DEBIT'::tx_direction end,p_amount,before,afterb,txid,p_note,p_idempotency_key);insert into audit_logs(user_id,action,module,reference_id,new_data) values(auth.uid(),'ADMIN_'||upper(p_direction),'WALLET',txid,jsonb_build_object('target_user',t.id,'amount',p_amount,'before',before,'after',afterb));return jsonb_build_object('transaction_id',txid,'balance',afterb);end$$;

create or replace function public.create_topup_request(p_requested_vcoin numeric,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare p profiles%rowtype;rid text;ch numeric;begin select * into p from profiles where id=auth.uid();if p.status<>'active' then raise exception 'Account not active';end if;if p_requested_vcoin<=0 then raise exception 'Invalid amount';end if;if exists(select 1 from topup_requests where idempotency_key=p_idempotency_key) then return jsonb_build_object('duplicate',true);end if;ch:=calc_charge(p.master_id,'VCOIN_TOPUP',p_requested_vcoin);rid:='TOP-'||upper(substr(encode(gen_random_bytes(9),'hex'),1,18));insert into topup_requests(request_id,user_id,master_id,requested_vcoin,topup_charge,total_payment,idempotency_key) values(rid,p.id,p.master_id,p_requested_vcoin,ch,p_requested_vcoin+ch,p_idempotency_key);return jsonb_build_object('request_id',rid,'requested_vcoin',p_requested_vcoin,'charge',ch,'status','pending');end$$;

create or replace function public.create_bank_request(p_vcoin_amount numeric,p_bank_account_id text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare p profiles%rowtype;w wallets%rowtype;b bank_accounts%rowtype;rid text;ch numeric;rate numeric:=1;begin select * into p from profiles where id=auth.uid();select * into b from bank_accounts where id=p_bank_account_id::uuid and user_id=p.id;if b.id is null then raise exception 'Bank account not found';end if;select coalesce((value->>'rate')::numeric,1) into rate from system_settings where key='BANK_VCOIN_RATE';ch:=calc_charge(p.master_id,'BANK_TRANSFER',p_vcoin_amount);select * into w from wallets where user_id=p.id for update;if w.vcoin_balance-w.locked_balance<p_vcoin_amount then raise exception 'Insufficient available balance';end if;update wallets set locked_balance=locked_balance+p_vcoin_amount where id=w.id;rid:='BNK-'||upper(substr(encode(gen_random_bytes(9),'hex'),1,18));insert into bank_transfer_requests(request_id,user_id,master_id,bank_account_id,vcoin_amount,conversion_rate,gross_bank_amount,transfer_charge,final_bank_amount,status,idempotency_key) values(rid,p.id,p.master_id,b.id,p_vcoin_amount,rate,p_vcoin_amount*rate,ch,greatest((p_vcoin_amount-ch)*rate,0),'pending',p_idempotency_key);return jsonb_build_object('request_id',rid,'rate',rate,'charge',ch,'final_amount',greatest((p_vcoin_amount-ch)*rate,0));end$$;

create or replace function public.run_wallet_maintenance() returns integer language plpgsql security definer set search_path=public as $$declare r record;w wallets%rowtype;n int:=0;txid text;begin for r in select * from wallet_maintenance_rules where is_active=true and (last_run_at is null or last_run_at <= now()-(frequency_hours||' hours')::interval) loop for w in select w.* from wallets w join profiles p on p.id=w.user_id where w.status='active' and p.status='active' and (r.master_id is null or p.master_id=r.master_id) and w.vcoin_balance-w.locked_balance-r.charge_amount>=r.minimum_wallet_balance for update loop if r.charge_amount>0 then txid:='MNT-'||upper(substr(encode(gen_random_bytes(9),'hex'),1,18));insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(txid,w.id,'MAINTENANCE_FEE','DEBIT',r.charge_amount,w.vcoin_balance,w.vcoin_balance-r.charge_amount,txid,'Wallet maintenance',txid);update wallets set vcoin_balance=vcoin_balance-r.charge_amount where id=w.id;insert into charge_history(user_id,transaction_type,reference_id,amount) values(w.user_id,'WALLET_MAINTENANCE',txid,r.charge_amount);n:=n+1;end if;end loop;update wallet_maintenance_rules set last_run_at=now() where id=r.id;end loop;return n;end$$;

-- RLS
alter table public.profiles enable row level security;
alter table public.wallets enable row level security;
alter table public.wallet_transactions enable row level security;
alter table public.vcoin_transfers enable row level security;
alter table public.topup_requests enable row level security;
alter table public.charge_history enable row level security;
alter table public.commissions enable row level security;
alter table public.crypto_assets enable row level security;
alter table public.crypto_conversion_requests enable row level security;
alter table public.bank_accounts enable row level security;
alter table public.bank_transfer_requests enable row level security;
alter table public.notifications enable row level security;
alter table public.audit_logs enable row level security;
alter table public.user_permissions enable row level security;

drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles for select to authenticated
using (id = auth.uid() or public.app_current_role() in ('super_admin','admin') or (public.app_current_role() = 'master' and master_id = auth.uid()));

drop policy if exists wallets_select on public.wallets;
create policy wallets_select on public.wallets for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or exists (select 1 from public.profiles p where p.id = wallets.user_id and p.master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists ledger_select on public.wallet_transactions;
create policy ledger_select on public.wallet_transactions for select to authenticated
using (exists (select 1 from public.wallets w where w.id = wallet_id and (w.user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or exists (select 1 from public.profiles p where p.id = w.user_id and p.master_id = auth.uid() and public.app_current_role() = 'master'))));

drop policy if exists transfers_select on public.vcoin_transfers;
create policy transfers_select on public.vcoin_transfers for select to authenticated
using (sender_user_id = auth.uid() or receiver_user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or exists (select 1 from public.profiles p where p.id in (sender_user_id,receiver_user_id) and p.master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists topup_select on public.topup_requests;
create policy topup_select on public.topup_requests for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or (master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists charge_select on public.charge_history;
create policy charge_select on public.charge_history for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or (master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists commission_select on public.commissions;
create policy commission_select on public.commissions for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or (master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists crypto_assets_read on public.crypto_assets;
create policy crypto_assets_read on public.crypto_assets for select to authenticated
using (is_active = true or public.app_current_role() in ('super_admin','admin'));

drop policy if exists crypto_req_select on public.crypto_conversion_requests;
create policy crypto_req_select on public.crypto_conversion_requests for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or (master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists bank_accounts_owner on public.bank_accounts;
create policy bank_accounts_owner on public.bank_accounts for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin'));

drop policy if exists bank_req_select on public.bank_transfer_requests;
create policy bank_req_select on public.bank_transfer_requests for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin') or (master_id = auth.uid() and public.app_current_role() = 'master'));

drop policy if exists notif_owner on public.notifications;
create policy notif_owner on public.notifications for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin'));

drop policy if exists audit_admin on public.audit_logs;
create policy audit_admin on public.audit_logs for select to authenticated
using (public.app_current_role() in ('super_admin','admin'));

drop policy if exists perms_self on public.user_permissions;
create policy perms_self on public.user_permissions for select to authenticated
using (user_id = auth.uid() or public.app_current_role() in ('super_admin','admin'));

-- direct writes: profile self fields only are intentionally omitted from this baseline; use controlled server actions/RPCs.
revoke update on wallets from authenticated;revoke insert,update,delete on wallet_transactions from authenticated;


-- Extended request processing functions
create or replace function public.create_crypto_request(p_crypto_asset_id text,p_vcoin_amount numeric,p_destination_wallet text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare p profiles%rowtype;w wallets%rowtype;a crypto_assets%rowtype;rid text;ch numeric;net numeric;gross numeric;begin select * into p from profiles where id=auth.uid();if p.status<>'active' then raise exception 'Account not active';end if;if p_vcoin_amount<=0 then raise exception 'Invalid amount';end if;if exists(select 1 from crypto_conversion_requests where idempotency_key=p_idempotency_key) then return jsonb_build_object('duplicate',true);end if;select * into a from crypto_assets where id=p_crypto_asset_id::uuid and is_active=true;if a.id is null then raise exception 'Crypto asset not found';end if;ch:=calc_charge(p.master_id,'CRYPTO_CONVERSION',p_vcoin_amount);net:=p_vcoin_amount-ch-a.network_fee_vcoin;if net<=0 then raise exception 'Amount is too small after charges';end if;select * into w from wallets where user_id=p.id for update;if w.status<>'active' then raise exception 'Wallet frozen';end if;if w.vcoin_balance-w.locked_balance<p_vcoin_amount then raise exception 'Insufficient available balance';end if;update wallets set locked_balance=locked_balance+p_vcoin_amount,updated_at=now() where id=w.id;rid:='CRY-'||upper(substr(encode(gen_random_bytes(9),'hex'),1,18));gross:=p_vcoin_amount/a.vcoin_per_unit;insert into crypto_conversion_requests(request_id,user_id,master_id,crypto_asset_id,vcoin_amount,conversion_rate,gross_crypto_amount,conversion_charge,network_charge,final_crypto_amount,destination_wallet,status,idempotency_key) values(rid,p.id,p.master_id,a.id,p_vcoin_amount,a.vcoin_per_unit,gross,ch,a.network_fee_vcoin,net/a.vcoin_per_unit,p_destination_wallet,'pending',p_idempotency_key);return jsonb_build_object('request_id',rid,'asset',a.symbol,'rate',a.vcoin_per_unit,'conversion_charge',ch,'network_fee',a.network_fee_vcoin,'final_crypto',net/a.vcoin_per_unit);end$$;

create or replace function public.process_request(p_kind text,p_request_id text,p_action text,p_note text) returns jsonb language plpgsql security definer set search_path=public as $$declare me profiles%rowtype;uid uuid;mid uuid;wid uuid;amt numeric;chg numeric:=0;rid text;before numeric;locked_before numeric;afterb numeric;k text:=upper(p_kind);a text:=upper(p_action);begin select * into me from profiles where id=auth.uid();if me.role not in ('super_admin','admin','master') or me.status<>'active' then raise exception 'Not authorized';end if;if me.role='master' and not has_permission('APPROVE_REQUESTS') then raise exception 'Permission required';end if;if k='TOPUP' then select user_id,master_id,requested_vcoin,topup_charge,request_id into uid,mid,amt,chg,rid from topup_requests where id=p_request_id::uuid for update;if uid is null then raise exception 'Request not found';end if;if me.role='master' and mid is distinct from me.id then raise exception 'Not your assigned request';end if;if a='COMPLETE' then select id,vcoin_balance into wid,before from wallets where user_id=uid for update;afterb:=before+amt;update wallets set vcoin_balance=afterb,updated_at=now() where id=wid;insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(rid||'-C',wid,'TOPUP','CREDIT',amt,before,afterb,rid,'Top-up completed','PROC-'||rid);update topup_requests set status='completed',updated_at=now() where id=p_request_id::uuid;if chg>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'VCOIN_TOPUP',rid,chg);end if;else update topup_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;end if;elsif k='CRYPTO' then select user_id,master_id,vcoin_amount,conversion_charge+network_charge,request_id into uid,mid,amt,chg,rid from crypto_conversion_requests where id=p_request_id::uuid for update;if uid is null then raise exception 'Request not found';end if;if me.role='master' and mid is distinct from me.id then raise exception 'Not your assigned request';end if;select id,vcoin_balance,locked_balance into wid,before,locked_before from wallets where user_id=uid for update;if a='COMPLETE' then if locked_before<amt then raise exception 'Locked balance mismatch';end if;afterb:=before-amt;update wallets set vcoin_balance=afterb,locked_balance=locked_balance-amt,updated_at=now() where id=wid;insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(rid||'-D',wid,'CRYPTO_CONVERSION','DEBIT',amt,before,afterb,rid,'Crypto conversion completed','PROC-'||rid);update crypto_conversion_requests set status='completed',updated_at=now() where id=p_request_id::uuid;if chg>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'CRYPTO_CONVERSION',rid,chg);end if;insert into crypto_transactions(crypto_request_id,crypto_asset_id,wallet_address,crypto_amount,transaction_hash,network,processed_by,processed_at) select id,crypto_asset_id,destination_wallet,final_crypto_amount,nullif(p_note,''),a2.network,auth.uid(),now() from crypto_conversion_requests c join crypto_assets a2 on a2.id=c.crypto_asset_id where c.id=p_request_id::uuid;elsif a in ('REJECTED','CANCELLED') then update wallets set locked_balance=greatest(locked_balance-amt,0),updated_at=now() where id=wid;update crypto_conversion_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;else update crypto_conversion_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;end if;elsif k='BANK' then select user_id,master_id,vcoin_amount,transfer_charge,request_id into uid,mid,amt,chg,rid from bank_transfer_requests where id=p_request_id::uuid for update;if uid is null then raise exception 'Request not found';end if;if me.role='master' and mid is distinct from me.id then raise exception 'Not your assigned request';end if;select id,vcoin_balance,locked_balance into wid,before,locked_before from wallets where user_id=uid for update;if a='COMPLETE' then if locked_before<amt then raise exception 'Locked balance mismatch';end if;afterb:=before-amt;update wallets set vcoin_balance=afterb,locked_balance=locked_balance-amt,updated_at=now() where id=wid;insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(rid||'-D',wid,'BANK_TRANSFER','DEBIT',amt,before,afterb,rid,'Bank transfer completed','PROC-'||rid);update bank_transfer_requests set status='completed',updated_at=now() where id=p_request_id::uuid;if chg>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'BANK_TRANSFER',rid,chg);end if;insert into bank_transfer_transactions(bank_request_id,bank_reference_number,amount,processed_by,processed_at,remarks) select id,nullif(p_note,''),final_bank_amount,auth.uid(),now(),p_note from bank_transfer_requests where id=p_request_id::uuid;elsif a in ('REJECTED','CANCELLED') then update wallets set locked_balance=greatest(locked_balance-amt,0),updated_at=now() where id=wid;update bank_transfer_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;else update bank_transfer_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;end if;else raise exception 'Unknown request kind';end if;insert into audit_logs(user_id,action,module,reference_id,new_data) values(auth.uid(),a,k,p_request_id,jsonb_build_object('note',p_note));return jsonb_build_object('success',true,'kind',k,'action',a);end$$;

-- Function execution permissions
revoke all on function public.transfer_vcoin(text,numeric,text,text) from public;
revoke all on function public.admin_adjust_vcoin(text,numeric,text,text,text) from public;
revoke all on function public.create_topup_request(numeric,text) from public;
revoke all on function public.create_crypto_request(text,numeric,text,text) from public;
revoke all on function public.create_bank_request(numeric,text,text) from public;
revoke all on function public.process_request(text,text,text,text) from public;
revoke all on function public.has_permission(text) from public;

grant execute on function public.transfer_vcoin(text,numeric,text,text) to authenticated;
grant execute on function public.admin_adjust_vcoin(text,numeric,text,text,text) to authenticated;
grant execute on function public.create_topup_request(numeric,text) to authenticated;
grant execute on function public.create_crypto_request(text,numeric,text,text) to authenticated;
grant execute on function public.create_bank_request(numeric,text,text) to authenticated;
grant execute on function public.process_request(text,text,text,text) to authenticated;
grant execute on function public.has_permission(text) to authenticated;
